    imageAlt: "Hund sitzt neben einem Napf mit Hühnchen und Reis",
    content: `Durchfall ist einer der häufigsten Gründe, warum Hundehalter die Tierarztpraxis aufsuchen. In vielen Fällen steckt keine ernste Erkrankung dahinter, sondern ein kurzzeitig gereizter Magen-Darm-Trakt. Für diese akuten Fälle hat sich Schonkost bewährt. Das Ziel ist einfach: den Verdauungstrakt entlasten, Wasser und Energie liefern und gleichzeitig möglichst wenig reizen.

## Die klassische Schonkost: Hühnchen und Reis

**Mageres Hühnchen** (ohne Haut, ohne Knochen, ohne Gewürze) und **weich ausgekochter Reis** sind die bewährteste Kombination. Beides ist leicht verdaulich, arm an Fett und schont die gereizte Darmschleimhaut.

So bereitest du es zu:
- Hühnchenbrust in ungesalzenem Wasser gar kochen
- Reis sehr lang kochen, bis er fast zu Brei wird
- Mischungsverhältnis: etwa **⅓ Hühnchen, ⅔ Reis**
- Alles abkühlen lassen, dann in kleinen Portionen reichen

## Wie viel und wie oft?

Verteile die Tagesmenge auf **drei bis vier kleine Mahlzeiten**. Ein großes Mahl auf einmal kann den gereizten Magen überfordern. Die Gesamtmenge liegt in der Regel bei etwa **der Hälfte der normalen Futterration** — frag deinen Tierarzt, wenn du unsicher bist, wie viel für dein Tier passt.

## Wann wieder auf normales Futter umstellen?

Wenn der Kot nach **ein bis zwei Tagen** wieder fester wird und dein Hund munter ist, beginne langsam zurückzuleiten. Mische am dritten Tag etwa ein Viertel normales Futter unter die Schonkost, steigere täglich und sei nach fünf bis sieben Tagen vollständig zurück beim gewohnten Futter.

## Was du zusätzlich beachten solltest

- **Wasser ist Pflicht:** Durchfall entzieht dem Körper Flüssigkeit. Stell deinem Hund immer frisches Wasser zur Verfügung und beobachte, ob er trinkt.
- **Keine Milchprodukte:** Auch fettarmer Quark oder Joghurt ist für den angegriffenen Darm oft zu viel.
- **Kein Salz, kein Öl, keine Gewürze:** Die Schonkost soll möglichst reizarm sein.

## Häufige Fragen

### Darf ich statt Hühnchen auch Pute nehmen?
Ja. Magere Putenbrust ist ebenfalls gut geeignet und eine gute Alternative, wenn dein Hund Huhn nicht verträgt.

### Kann ich auch Fertigschonkost aus dem Handel nehmen?
Ja, es gibt spezielle Gastrointestinal-Diätfutter für Hunde. Lies die Etiketten und achte auf eine einfache, fettarme Zusammensetzung. Im Zweifel empfiehlt die Tierärztin das Passende.

### Muss ich beim Tierarzt vorbei?
Wenn Durchfall **länger als 48 Stunden** anhält, Blut beigemengt ist, dein Hund Fieber hat oder sich auffällig träge verhält, gehört er in die Praxis. Schonkost ersetzt keine tierärztliche Untersuchung bei ernsten Symptomen.

## Das Wichtigste in Kürze

- Hühnchen und Reis: einfach, leicht verdaulich, bewährt.
- Kleine Portionen, mehrere Mahlzeiten täglich.
- Nach ein bis zwei Tagen langsam zurück auf Normalkost überleiten.
- Bei anhaltenden oder ernsten Symptomen immer zum Tierarzt.`,
