    content: `Wenn Halter Schonkost für ihren Hund kochen, passiert ein häufiger Fehler: Sie würzen mit dem, was in der menschlichen Küche selbstverständlich ist — ein wenig Salz, etwas Brühe, Öl in die Pfanne. Für den Hund mit gereizstem Verdauungstrakt kann das die Symptome verschlechtern statt verbessern.

## Das Problem mit Salz

Hunde brauchen deutlich weniger Natrium als Menschen. Ein Teelöffel Salz kann für einen kleinen Hund bereits zu viel sein. In der Schonkost ist das Problem noch größer: Der gereizte Darm nimmt alles stärker wahr, und Salz kann die Schleimhaut zusätzlich reizen. Außerdem verändert es den Wasser-Elektrolyt-Haushalt — genau das, was ein Hund nach Durchfall oder Erbrechen gar nicht braucht.

**Merke: Gar kein Salz — nicht "wenig Salz".**

## Warum kein Öl?

Fette Zusätze wie Speiseöl verzögern die Magenentleerung. Der Magen bleibt länger beschäftigt, und das ist bei Magenproblemen genau das Gegenteil von dem, was wir wollen. Selbst ein kleiner Schuss Öl kann bei einem sensiblen Magen Übelkeit oder erneutes Erbrechen auslösen.

## Gewürze: Fast alle sind verboten

Zwiebelgewächse (Zwiebeln, Knoblauch, Lauch) sind für Hunde giftig — auch in kleinen Mengen und auch getrocknet. Paprika, Chili und viele andere Gewürze reizen den Magen. Selbst Muskat ist für Hunde giftig.

Die Regel für Schonkost lautet schlicht: **Keine Gewürze, keine Kräuter, keine Würzmischungen.**

## Auch Brühe ist keine gute Idee

Viele Halter kochen das Hühnchen in Brühe, um es schmackhafter zu machen. Das Problem: Fertigbrühen (Würfel, Tüten, Tetrapack) enthalten fast immer Salz, Hefeextrakt und Gewürze. Selbst gekochte Brühe aus Knochen kann viel Fett enthalten.

Koche das Hühnchen in **klarem Wasser** — das reicht.

## Wie motiviere ich einen futterunmotivierten Hund?

Wenn dein Hund die fade Schonkost verweigert:
- Leicht anwärmen (nicht erhitzen): Wärme verstärkt den Geruch
- Etwas von dem Kochwasser des Hühnchens darüber geben
- In sehr kleinen Happen anbieten
- Kurze Pause machen und dann erneut anbieten

## Häufige Fragen

### Ist ein Schuss Olivenöl wirklich so schlimm?
Ja, in der akuten Schonphase. Fett verzögert die Magenentleerung und belastet den Darm. Wenn dein Hund wieder gesund ist, ist ein kleiner Schuss Öl als Nahrungsergänzung grundsätzlich unbedenklich — aber in der Schonkost weglassen.

### Kann ich Kräuter wie Petersilie nehmen?
Kein Gewürzkräuter in der Schonkost. Auch Petersilie enthält ätherische Öle, die einen sensiblen Magen reizen können. Schlicht halten ist die Devise.

### Was wenn mein Hund das fade Futter gar nicht annimmt?
Ein kranker Hund, der ein bis zwei Mahlzeiten ablehnt, ist kein Notfall. Größere Essverweigerung über mehrere Mahlzeiten hinweg, besonders kombiniert mit anderen Symptomen, ist ein Grund für einen Tierarztbesuch.

## Das Wichtigste in Kürze

- Keine Gewürze, kein Salz, kein Öl in der Schonkost.
- Kein Knoblauch, keine Zwiebeln — diese sind für Hunde giftig.
- Hühnchen in klarem Wasser kochen, nicht in Brühe.
- Fade Schonkost ist Absicht — der Hund braucht Reizarmut, keine Gaumenfreude.`,
    seoTitle: "Schonkost Hund: Warum kein Salz, Öl oder Gewürze | BELLA",
    seoDescription:
      "Warum Gewürze, Salz und Öl in der Hundeschonkost verboten sind — und was du stattdessen tun kannst, wenn dein Hund die fade Kost verweigert.",
