      "Wenn dein Hund trotz normalem Fressen Gewicht verliert, steckt fast immer eine Erkrankung dahinter. Diese Ursachen gibt es und so gehst du vor.",
    keywords: ["Hund nimmt ab trotz Fressen", "Hund Untergewicht Ursache", "Hund abnehmen Krankheit", "Hund Gewichtsverlust Diagnose", "Hund dünn Tierarzt"],
