    title: "Schonkost nicht zur Dauerkost machen",
    shortDescription:
      "Hühnchen und Reis sind eine bewährte kurzfristige Schonkost — aber kein vollwertiges Alleinfutter. Was fehlt und wann du zurück zum normalen Futter wechseln solltest.",
