    imageUrl: "/images/tipps/diaet/11.jpg",
    imageAlt: "Hund frisst Hühnchen und Reis aus einem weißen Napf",
    content: `Hühnchen und Reis ist die bekannteste Schonkost für Hunde. Sie funktioniert gut — für ein bis drei Tage. Wer sie jedoch Woche für Woche füttert, weil der Hund sie gut akzeptiert, weil sie einfach zuzubereiten ist oder weil keine Zeit für die Rückleitung auf normales Futter war, schafft dabei unbemerkt einen Mangel.

## Was in der Hühnchen-Reis-Schonkost fehlt

**Calcium und Phosphor:**
Gekochtes Hühnchen und Reis liefern kaum das richtige Ca:P-Verhältnis. Langfristig kann das zu Knochenproblemen führen, besonders bei Welpen und Senioren.

**Vitamine und Spurenelemente:**
Vitamin E, Vitamin D, Zink, Jod — diese und andere Mikronährstoffe sind in einer Schonkost aus zwei Zutaten nicht ausreichend vorhanden. Ein vollwertiges Hundefutter ist eine biologisch komplexe Formel.

**Essenzielle Fettsäuren:**
Mageres Hühnchen enthält wenig Omega-3 und Omega-6 im richtigen Verhältnis. Der Bedarf für Haut, Fell und Zellmembranen bleibt ungedeckt.

**Taurin und andere Aminosäuren:**
Einige Aminosäuren, die für die Herzfunktion wichtig sind, sind in einer einseitigen Ration nicht ausreichend vertreten.

## Wie lange ist Schonkost angemessen?

In der Regel gilt: **nicht länger als 3–5 Tage**. Danach solltest du langsam auf das normale Futter zurückleiten — über 5–7 Tage gemischt, immer mehr normales Futter beigemischt.

Wenn die Magen-Darm-Probleme nach 2–3 Tagen Schonkost nicht nachlassen, ist der Tierarzt gefragt. Dann ist die Schonkost kein temporäres Mittel mehr, sondern ein Hinweis auf ein tiefer liegendes Problem.

## Was tun, wenn Schonkost dauerhaft nötig ist?

Manchmal schlägt das normale Futter dauerhaft nicht an. In diesem Fall gibt es zwei seriöse Wege:

1. **Kommerzielles GI-Diätfutter:** Spezielle Gastrointestinal-Diäten (z. B. für empfindlichen Verdauungstrakt) sind vollwertig formuliert und leicht verdaulich.
2. **Berechnete Kochration:** Wer dauerhaft kochen möchte, lässt die Rezeptur von einem Ernährungsberater für Hunde berechnen. Nur so ist sichergestellt, dass alle Nährstoffe abgedeckt sind.

## Häufige Fragen

### Mein Hund verträgt seit Jahren nur Hühnchen und Reis. Was nun?
Das klingt nach einer Futtermittelunverträglichkeit oder einem empfindlichen Darm. Eine tierärztliche Abklärung und ggf. eine Eliminationsdiät können helfen, die eigentliche Ursache zu finden. Dauerhaft Hühnchen und Reis ist keine Lösung.

### Kann ich Hühnchen-Reis durch Pute-Kartoffel ersetzen?
Ja, die Nährstofflücken bleiben aber ähnlich. Das Prinzip ist das gleiche: kurzfristig geeignet, langfristig nicht vollwertig.`,
