    id: 36,
    slug: "selbst-gekochte-diaet-bilanzieren",
    title: "Selbst gekochte Diät bilanzieren lassen",
    shortDescription:
      "Eine dauerhaft selbst gekochte Ration braucht eine berechnete Rezeptur. Sonst entstehen Nährstofflücken, die sich erst nach Wochen oder Monaten zeigen.",
    level: 2,
    tags: ["selbstgekocht", "naehrwerte"],
    imageUrl: "/images/tipps/diaet/12.jpg",
    imageAlt: "Hunde-Mahlzeit aus frischen Zutaten mit einer Nährwerttabelle daneben",
    content: `Selbst kochen für den Hund liegt im Trend — und es hat echte Vorteile: Kontrolle über Zutaten, Frische, Flexibilität. Aber im Gegensatz zu einem kommerziellen Hundefutter ist eine selbst zusammengestellte Ration kein automatisch ausgewogenes Produkt. Ohne Berechnung fehlen fast immer wichtige Nährstoffe.

## Das Problem mit dem Bauchgefühl

Ein Hundehalter, der drei Zutaten kombiniert — Rindfleisch, Kartoffel, Karotte — sieht ein ansprechendes Gericht. Der Hund frisst es gerne. Alles scheint gut. Was unsichtbar bleibt: Die Ration enthält zu wenig Calcium, kein Jod, kaum Vitamin D, kein ausgewogenes Omega-3-zu-Omega-6-Verhältnis. Die Folgen zeigen sich erst nach Wochen oder Monaten: Fell wird stumpf, Knochen werden fragil, Immunfunktion lässt nach.

## Wer eine Ration berechnen kann

**Tierärztliche Ernährungsberater:**
Tierärzte mit Zusatzqualifikation in Ernährungsberatung oder spezialisierte Ernährungsberaterinnen für Hunde (z. B. mit Abschluss in Tierernährung) können eine Ration auf den spezifischen Hund zuschneiden: Gewicht, Alter, Erkrankung, Aktivitätsniveau.

**Online-Tools (mit Vorsicht):**
Es gibt Berechnungstools und Software (z. B. auf Basis der NRC- oder FEDIAF-Empfehlungen). Diese Tools sind hilfreich, ersetzen aber keine individuelle Beratung, besonders wenn eine Erkrankung im Spiel ist.

## Was eine Rezeptur enthält

Eine seriöse Kochrezeptur gibt nicht nur Zutaten und Mengen vor, sondern auch:
- Welche Ergänzungsmittel (Supplement-Mix, Kalzium, ggf. Öle) zugegeben werden müssen
- Welche Mengen in Gramm für diesen speziellen Hund pro Tag nötig sind
- Wie die Ration bei Gewichtsveränderung angepasst wird

## Wann braucht jede Kochration eine Berechnung?

**Immer** — wenn sie die Hauptmahlzeit ist und dauerhaft gefüttert wird. Kurzfristige Schonkost (1–3 Tage) braucht keine Präzisionsberechnung. Eine wöchentliche oder dauerhafte Kochration schon.

## Häufige Fragen

### Kann ich eine fertige Hundefutter-Supplikations-Mischung kaufen und selbst hinzufügen?
Ja, Supplement-Mischungen wie Balance IT oder ähnliche Produkte helfen dabei, eine Basisversorgung abzudecken. Wichtig: Die Dosierung muss auf die konkrete Ration abgestimmt sein.

### Wie oft muss ich eine Rezeptur aktualisieren?
Bei Gesundheitsveränderungen, bei deutlicher Gewichtsänderung (mehr als 10 %) und beim Lebenszykluswechsel (Welpe → Adult → Senior). Beim stabilen, gesunden Hund reicht eine jährliche Überprüfung.`,
