    imageAlt: "Flohsamenschalen in einem Löffel mit einer Wasserschüssel daneben",
    content: `Flohsamenschalen (Psyllium) gehören zu den wirkungsvollsten natürlichen Ballaststoffen — und gleichzeitig zu denen, die am häufigsten falsch angewendet werden. Falsch dosiert oder trocken gegeben können sie genau das Gegenteil dessen bewirken, was du anstrebst.

## Was Flohsamenschalen so besonders macht

Flohsamenschalen bestehen zu einem großen Teil aus löslichen Ballaststoffen, die ein Vielfaches ihres Eigengewichts an Wasser binden können. Sie bilden ein Gel, das:
- Bei **Verstopfung** den Kot aufweicht und die Passage erleichtert
- Bei **Durchfall** überschüssiges Wasser bindet und den Stuhl festigt
- Die **Darmschleimhaut** schützt und beruhigt

Dieses „beide Richtungen"-Prinzip macht Flohsamenschalen zu einer vielseitigen Ergänzung — wenn sie richtig eingesetzt werden.

## So wendest du Flohsamenschalen beim Hund an

**Schritt 1: Einweichen**
Gib die Flohsamenschalen vor der Fütterung in lauwarmes Wasser — mindestens 1:10 (1 Teil Flohsamen, 10 Teile Wasser). Warte 5–10 Minuten, bis sie gequollen sind. Das Ergebnis ist eine gelartige Masse.

**Schritt 2: Unter das Futter mischen**
Die gequollene Masse wird unter das Futter gemischt — nicht separat geben, das frisst kaum ein Hund freiwillig.

**Schritt 3: Wasser anbieten**
Nach der Mahlzeit muss immer frisches Wasser zur Verfügung stehen. Die Ballaststoffe ziehen auch im Darm noch Wasser — ohne ausreichende Flüssigkeitszufuhr droht Verstopfung statt Hilfe.

## Dosierungsempfehlung

| Körpergewicht | Startmenge |
|---|---|
| unter 10 kg | ¼ TL |
| 10–25 kg | ½ TL |
| über 25 kg | 1 TL |

Langsam steigern, wenn nötig. Nie direkt mit der vollen Dosis beginnen.

## Wann Flohsamenschalen nicht geeignet sind

- Bei **Schluckschwierigkeiten** (Megaösophagus) — Quellgefahr in der Speiseröhre
- Bei **Darmverschluss oder -obstruktion** — absolut kontraindiziert
- Bei **unzureichender Wasseraufnahme** — dann lieber Kürbis verwenden

## Häufige Fragen

### Kann ich die Schalen auch ins Trockenfutter mischen?
Besser erst quellen lassen. Trockene Schalen im Futter quellen im Magen, was zwar meist harmlos ist, aber nicht ideal. Gequollen ist sicherer und verträglicher.

### Wie lange kann ich Flohsamenschalen dauerhaft einsetzen?
Kurzzeitig ja, als Dauerlösung sollte die Ursache der Darm­probleme geklärt sein. Für Hunde mit chronischen Analdrüsenproblemen ist eine dauerhafte Ergänzung in Absprache mit dem Tierarzt möglich.`,
