    title: "Bei Krebspatienten den Appetit unterstützen",
    shortDescription:
      "Tumorkranke Hunde fressen oft schlecht. Hochwertiges, schmackhaftes und energiereiches Futter hilft, den Körper in der Behandlung zu stabilisieren.",
