    slug: "diaetewechsel-nicht-abrupt",
    title: "Diätwechsel niemals abrupt",
    shortDescription:
      "Auch der Wechsel auf eine medizinische Diät braucht eine Übergangsphase. Warum abrupte Umstellungen selbst bei dringend benötigten Diäten mehr schaden als nützen.",
    level: 1,
    tags: ["umstellung", "diaet"],
    imageUrl: "/images/tipps/diaet/2.jpg",
    imageAlt: "Futternapf, halb mit altem, halb mit neuem Diätfutter gefüllt",
    content: `Die Diagnose ist gestellt, das Diätfutter ist bestellt — und du willst sofort anfangen. Verständlich. Aber selbst wenn das alte Futter das Problem war und das neue die Lösung ist, braucht der Verdauungstrakt Zeit, sich anzupassen. Ein abrupter Wechsel — auch auf das beste Futter der Welt — kann Durchfall, Erbrechen und Bauchschmerzen verursachen.

## Was im Darm beim Futterwechsel passiert

Die Darmflora ist auf das aktuelle Futter eingestellt. Sie produziert bestimmte Enzyme für die vorliegenden Zutaten, und die Bakterienstämme sind an die Zusammensetzung gewöhnt. Ein plötzlicher Wechsel bedeutet für die Darmflora: neues Substrat, andere Verhältnisse, Stress. Die Folge sind häufig vorübergehende Verdauungsstörungen.

## Die richtige Umstellungsphase auch für medizinische Diäten

Ausnahme: Bei bestimmten Erkrankungen (z. B. schwere Pankreatitis in der Akutphase) kann der Tierarzt eine sofortige Umstellung anordnen. In diesem Fall überwiegen die Risiken der alten Ernährung die Umstellungsprobleme. Das ist aber die Ausnahme — frag immer nach.

**Normale Empfehlung für medizinische Diäten:**
- Tag 1–3: 25 % neu / 75 % alt
- Tag 4–6: 50 % / 50 %
- Tag 7–10: 75 % / 25 %
- Ab Tag 10–14: 100 % neue Diät

## Besonderheit bei Eliminationsdiäten

Bei der Ausschlussdiät ist eine Mischungsphase nicht möglich — das alte Futter enthält die Allergene, die ausgeschlossen werden sollen. Hier wird in der Regel sofort auf das neue Futter gewechselt. Die ersten Tage können daher unruhiger sein, aber das ist unvermeidbar.

## Symptome während der Umstellung

Milde Symptome in den ersten 3–5 Tagen sind normal:
- Weicherer Kot
- Einmaliges Erbrechen
- Leichte Blähungen

Nicht normal und Grund zum Abbruch:
- Blut im Stuhl oder Erbrochenen
- Starke Apathie
- Kein Fressen über 24 Stunden hinaus

## Häufige Fragen

### Was, wenn der Hund das alte Futter ganz verweigert und nur das neue will?
Wenn er das neue Diätfutter gut verträgt, kannst du schneller umstellen. Beobachte den Kot und die Energie für ein paar Tage besonders aufmerksam.

### Kann ich bei sehr kranken Hunden langsamer umstellen?
Ja. Bei sehr geschwächten Tieren kann eine 3-Wochen-Umstellung sinnvoll sein. Sprich das mit dem Tierarzt ab.`,
