    imageAlt: "Selbst gebackene Hundeleckerlis aus Diätfutter auf einem Backblech",
    content: `Eine strikte Diät bedeutet nicht, dass der Hund keine Belohnungen mehr bekommt. Gerade beim Training ist die Möglichkeit, Leckerlis einzusetzen, wichtig für die Motivation. Die Lösung ist simpel und dauert nur wenig Zeit: Leckerlis aus dem eigenen Diätfutter herstellen.

## Das Prinzip

Aus dem erlaubten Diätfutter (Nass- oder Trockenfutter) lassen sich kleine, handliche Snacks herstellen, die exakt die gleiche Zusammensetzung haben wie das Hauptfutter — und damit die Diät nicht brechen.

## Methode 1: Trockene Bröckchen aus Nassfutter

1. Nassfutter gleichmäßig dünn auf einem mit Backpapier ausgelegten Blech verteilen (ca. 5 mm dick)
2. Bei 80–100 °C im Ofen für 2–3 Stunden trocknen (nicht backen)
3. Abkühlen lassen, in kleine Stücke brechen
4. In einem luftdichten Behälter im Kühlschrank bis zu 5 Tage aufbewahren

Diese Bröckchen sind fest, lassen sich gut handhaben und riechen intensiv — perfekt als Training-Reward.

## Methode 2: Trockenfutter-Bröckchen einweichen und formen

1. Trockenfutter kurz mit warmem Wasser aufweichen
2. Zu kleinen Kugeln formen
3. Im Ofen bei 100 °C für 30–45 Minuten festigen
4. Kühl und trocken aufbewahren

## Methode 3: Getrocknetes Fleisch aus erlaubter Proteinquelle

Wenn die Diät Känguru erlaubt: Kängurufleisch in dünne Streifen schneiden, bei 70 °C für 6–8 Stunden im Backofen oder Dörrautomat trocknen. Das Ergebnis ist ein hochwertiger, sauberer Leckerli ohne Zusätze.

## Was du beachten solltest

- **Futtertagebuch anpassen:** Wenn die Leckerlis von der Tagesmenge abgehen sollen, entsprechend weniger Hauptfutter geben
- **Keine Zusätze:** Kein Salz, keine Gewürze, kein Öl
- **Haltbarkeit beachten:** Selbst hergestellte Leckerlis haben keine Konservierungsmittel — kurze Haltbarkeit einplanen

## Häufige Fragen

### Kann ich auch selbst hergestellte Leckerlis aus zwei erlaubten Zutaten machen?
Wenn die Diät eine Proteinquelle und eine Kohlenhydratquelle erlaubt, kannst du theoretisch beides kombinieren — aber nur wenn beides ausdrücklich Teil der Diätformel ist.

### Wie viele Leckerlis am Tag sind in der Diät okay?
Faustregel: Die Leckerlis sollten maximal 10 % der täglichen Kalorienmenge ausmachen. Bei sehr kalorienreichen Diäten entsprechend weniger.`,
