    imageUrl: "/images/tipps/diaet/8.jpg",
    imageAlt: "Kleiner Welpe liegt schwach neben seinem Futternapf",
    content: `Was bei einem ausgewachsenen Hund ein vernünftiges Mittel zur Magen-Erholung ist — eine kurze Nahrungspause —, kann bei einem Welpen lebensbedrohlich werden. Welpen haben im Vergleich zu adulten Hunden einen deutlich höheren Energiebedarf pro Körperkilogramm, sehr begrenzte Glykogenreserven und eine schnelle Tendenz zur Hypoglykämie (Unterzuckerung).

## Warum Welpen so anfällig sind

**Hoher Energiebedarf:**
Welpen wachsen rasant — ihr Energiebedarf pro kg Körpermasse ist deutlich höher als bei adulten Hunden. Das Gehirn und die roten Blutkörperchen sind auf kontinuierliche Glukoseversorgung angewiesen.

**Kleine Glykogenspeicher:**
Leber und Muskeln speichern Glukose als Glykogen. Bei Welpen sind diese Speicher klein — reichen nur für wenige Stunden.

**Schlechte Thermoregulation:**
Kleine Welpen können ihre Körperwärme noch schlechter halten. Kälte erhöht den Energieverbrauch, was die Unterzuckerungsgefahr verstärkt.

## Anzeichen von Unterzuckerung beim Welpen

- Zittern
- Schwäche, Teilnahmslosigkeit
- Taumeln
- Im schlimmsten Fall Krämpfe und Bewusstlosigkeit

Das kann sich innerhalb von Stunden entwickeln — weshalb jede Nahrungspause bei Welpen ein Risiko ist.

## Was du bei einem Welpen mit Magenproblemen tun solltest

1. **Sofort den Tierarzt kontaktieren** — auch wenn es eine Uhrzeit ist, zu der du es selbst noch managen könntest
2. **Kleine Mengen anbieten** — wenn der Welpe überhaupt versucht zu fressen, kleine Portionen ruhig anbieten
3. **Wasser immer bereitstellen**
4. **Im Zweifel sofort zur Klinik** — Welpen können sich rasend schnell verschlechtern

## Was bei leichten Fällen kurzfristig helfen kann

Falls der Tierarzt eine kurze Wartephase von maximal 2–3 Stunden bestätigt: Reiswasser oder stark verdünnte Hundemilch können als Überbrückung gegeben werden. Aber das ist keine Eigenentscheidung — Rücksprache ist Pflicht.

## Häufige Fragen

### Ab wann gilt ein Hund nicht mehr als „Welpe" in diesem Sinn?
In der Praxis bis etwa 3–4 Monate. Mit wachsender Körpermasse und reiferem Stoffwechsel sinkt das Hypoglykämierisiko. Aber: Zwergrassen (Chihuahua, Yorkshire Terrier) bleiben länger anfällig.

### Kann ich meinem Welpen bei Übelkeit etwas geben, das hilft?
Nur nach Rücksprache. Manche Tierärzte empfehlen eine sehr kleine Menge Honig auf die Schleimhäute als Sofortmaßnahme bei Unterzuckerungsverdacht — aber das ersetzt keine veterinärmedizinische Versorgung.`,
