    title: "Bei Gelenkdiät auf Omega-3 setzen",
    shortDescription:
      "Diätfutter für Gelenkpatienten enthält oft EPA und DHA. Warum diese Fettsäuren Entzündungen lindern können und was du bei der Wahl des Futters beachten solltest.",
    level: 2,
    tags: ["gelenke", "diaet"],
    imageUrl: "/images/tipps/diaet/10.jpg",
    imageAlt: "Hund mit Gelenkproblemen wird behandelt, Lachsöl im Vordergrund",
    content: `Arthrose, Hüftdysplasie, Ellenbogenprobleme — Gelenkerkrankungen sind beim Hund häufig und schmerzhaft. Neben Medikamenten, Physiotherapie und ggf. Gewichtsmanagement ist die Ernährung ein wirksamer Begleiter. Besonders Omega-3-Fettsäuren spielen dabei eine wichtige Rolle.

## Wie Omega-3 bei Gelenken wirkt

EPA (Eicosapentaensäure) und DHA (Docosahexaensäure) sind langkettige Omega-3-Fettsäuren, die aus Fischöl oder Algenöl gewonnen werden. Sie wirken auf mehreren Ebenen:

- **Entzündungshemmend:** EPA hemmt die Produktion von Prostaglandinen und Leukotrienen — Botenstoffen, die Entzündungen im Gelenk antreiben
- **Knorpelschutzend:** DHA unterstützt die Zellfunktion im Knorpelgewebe
- **Schmerzlindernd:** In mehreren Studien konnte gezeigt werden, dass Hunde mit Arthrose bei hoher EPA/DHA-Zufuhr weniger Schmerzmedikamente brauchten

## Was eine gute Gelenkdiät enthält

Professionelle Gelenkdiätfutter (z. B. Hill's j/d, Royal Canin Mobility) enthalten:
- **Hohe EPA/DHA-Gehalte** — deutlich über dem in normalem Futter
- **Glucosamin und Chondroitinsulfat** — Bausteine des Knorpels
- **L-Carnitin** — wenn begleitendes Übergewicht ein Thema ist
- **Antioxidantien** (Vitamin E, C) — schützen Gelenkgewebe vor oxidativem Stress

## Dosierung bei Zufütterung von Fischöl

Wenn du normales Futter gibst und Omega-3 separat ergänzt: Richtwert für EPA+DHA ist etwa 50–75 mg je kg Körpergewicht täglich, verteilt auf die Mahlzeiten. Starte niedrig und steigere langsam — zu viel Fischöl kann Durchfall verursachen.

Wichtig: Hochdosiertes Fischöl kann die Blutgerinnung beeinflussen. Vor Operationen mit dem Tierarzt besprechen.

## Häufige Fragen

### Sind pflanzliche Omega-3-Quellen (Leinöl) gleichwertig?
Nein. Leinöl enthält ALA (Alpha-Linolensäure), die der Hund nur ineffizient in EPA/DHA umwandeln kann. Für entzündungshemmende Wirkung sind EPA und DHA aus Fisch- oder Algenöl nötig.

### Kann ich neben dem Gelenkdiätfutter noch Fischöl zugeben?
Nur wenn das Diätfutter nicht schon ausreichend EPA/DHA enthält. Manche Premium-Gelenkfutter sind bereits vollständig formuliert — Doppelgabe kann zu Überdosierung führen.`,
