    title: "Schonkost-Rezept einfach halten",
    shortDescription:
      "Zwei bis drei Zutaten reichen für eine gute Schonkost. Je einfacher die Zusammensetzung, desto geringer die Reizbelastung für einen angegriffenen Verdauungstrakt.",
    level: 0,
    tags: ["schonkost", "zubereitung"],
    imageUrl: "/images/tipps/diaet/12.jpg",
    imageAlt: "Drei einfache Zutaten für Hundeschonkost: Hühnchen, Reis, Karotte",
    content: `Wenn es dem Hund nicht gut geht, greifen manche Halter zum Kochbuch. Fünf Zutaten, selbst gemacht, viel Liebe drin — und leider auch viel zu viel auf einmal für einen gereizten Magen-Darm-Trakt. Der Grundsatz bei Schonkost lautet: **so einfach wie möglich**.

## Warum weniger mehr ist

Je mehr Zutaten in einer Mahlzeit, desto mehr Verdauungsarbeit ist nötig. Ein Magen-Darm-System in Aufruhr braucht keine komplexen Rezepte — es braucht ein bis zwei leicht verdauliche Zutaten, die wenig Enzymarbeit erfordern und die Darmschleimhaut kaum belasten.

## Das Grundprinzip

**Eine Proteinquelle + eine Kohlenhydratquelle:**
- Mageres Hühnchen + weich ausgekochter Reis
- Magere Pute + Kartoffel (gut gegart)
- Kabeljau oder Seelachs + Reis
- Magerquark + Reis (wenn Milchprotein verträglich)

Mehr braucht es nicht. Kein Öl, kein Salz, keine Gewürze, keine Brühe (enthält Salz und Aromen).

## Mischverhältnis

Für eine typische Schonkost:
- **⅓ Protein, ⅔ Kohlenhydrat**

Der Kohlenhydratanteil überwiegt, weil er leichter verdaulich ist und den gereizten Darm beruhigt. Protein ist wichtig, aber in großen Mengen schwerer zu verdauen.

## Was optional ergänzt werden kann

Nach ein bis zwei Tagen stabiler Toleranz kann optional eine kleine Menge Kürbispüree (lösliche Ballaststoffe) hinzugefügt werden — hilft bei der Regulierung des Stuhlgangs. Das ist aber kein Muss.

## Was du vermeiden solltest

- **Mehrere Proteinquellen:** Hühnchen UND Ei UND Quark = zu viel auf einmal
- **Gemüse in Menge:** Karotten, Zucchini, Brokkoli können zwar gut sein, aber in der akuten Phase ist weniger mehr
- **Selbst gemachte Brühe:** Klingt gut, enthält aber oft Zwiebelreste, Lorbeer, Salz — alles ungünstig

## Häufige Fragen

### Kann ich Schonkost auch für gesunde Hunde geben, wenn sie Abwechslung wollen?
Schonkost ist bewusst nährstoffärmer formuliert als vollwertiges Futter. Für gesunde Hunde dauerhaft ungünstig — als gelegentliche Mahlzeit okay, wenn danach wieder vollwertiges Futter folgt.

### Muss ich die Zutaten immer frisch zubereiten?
Für ein bis zwei Tage im Voraus kochen und kühlen ist in Ordnung. Aber nicht einfrieren und auftauen für Schonkostzwecke — die Textur des Reises leidet stark.`,
