    content: `Reis ist die klassische Kohlenhydratquelle in der Hundeschonkost — bewährt, leicht verdaulich, einfach zuzubereiten. Aber was, wenn der Hund auf Getreide empfindlich reagiert, oder wenn Reis gerade nicht zu Hause ist? Die einfachste Alternative ist die Kartoffel.

## Warum Kartoffel geeignet ist

**Getreidefreie Stärke:**
Kartoffeln sind von Natur aus glutenfrei und enthalten keine Getreideproteine. Für Hunde mit Getreide-Unverträglichkeit oder für die Schonkost im Rahmen einer getreidefreien Diät sind sie gut geeignet.

**Leicht verdaulich:**
Gut durchgekochte Kartoffel ist sehr leicht verdaulich — die Stärke wird im Dünndarm gut aufgenommen, ohne viel Fermentation im Dickdarm.

**Sättigend und energiereich:**
Kartoffeln liefern schnell verfügbare Energie — gut für einen Hund, der geschwächt ist.

## Was du beachten solltest

**Nur gekocht, niemals roh:**
Rohe Kartoffeln enthalten Solanin — ein natürliches Gift, das besonders in der Schale und in grünen Stellen steckt. Immer durchgaren und schälen.

**Schale entfernen:**
Auch nach dem Kochen die Schale entfernen — sie ist schwerer verdaulich und enthält mehr Solanin.

**Keine grünen Kartoffeln:**
Grüne Stellen und Keime unbedingt großzügig abschneiden — sie enthalten erhöhte Solanin-Konzentrationen.

**Keine Würze:**
Keine Butter, kein Salz, keine Milch — die Kartoffel wird pur, in Wasser gekocht, serviert.

## Zubereitung für Schonkost

1. Kartoffeln schälen, in Stücke schneiden
2. In Wasser ohne Salz weich kochen (20–25 Minuten)
3. Abkühlen lassen, grob zerdrücken oder als Stücke lassen
4. Mit gekochtem, mageren Fleisch mischen

## Verhältnis und Menge

Gleich wie beim Reis-Rezept: ⅓ Protein, ⅔ Kartoffel. Beginn mit der Hälfte der normalen Futterration, auf 3–4 kleine Mahlzeiten aufteilen.

## Häufige Fragen

### Ist Süßkartoffel eine gute Alternative zu normaler Kartoffel?
Ja! Süßkartoffel (Batate) ist sogar noch leichter verdaulich und enthält mehr Ballaststoffe. Ebenfalls immer kochen und schälen.

### Kann ich auch Kartoffelpüree aus der Packung nehmen?
Nein — Fertigpüree enthält fast immer Salz, Milchpulver und Aromen. Das ist für Schonkostzwecke nicht geeignet.`,
