    title: "Pute als magere Proteinquelle",
    shortDescription:
      "Putenbrust ist sehr fettarm und gut verträglich — eine ausgezeichnete Basis für schonende Diäten, Schonkost und als Monoprotein-Alternative zu Hühnchen.",
    level: 1,
    tags: ["schonkost", "pute"],
