    imageAlt: "Gekochte Putenbrust auf einem Schneidebrett für die Hundeschonkost",
    content: `Hühnchen ist der König der Hundeschonkost — aber Pute ist ein würdiger Alternativkandidat. Putenbrust ist noch fettärmer als Hähnchenbrust, gut verdaulich und für viele Hunde ein „neues" Protein, das die Zahl der potenziellen Auslöser reduziert.

## Warum Pute für Hunde empfehlenswert ist

**Extrem fettarm:**
Putenbrust enthält etwa 1–2 g Fett pro 100 g gekochtes Fleisch — einer der niedrigsten Fettgehalte unter allen Fleischquellen. Ideal für Pankreatitis-Patienten, Hunde mit Fettstoffwechselproblemen und alle, die eine echte Schonkost brauchen.

**Hochverdauliches Protein:**
Das Protein der Putenbrust ist von sehr guter Qualität und wird im Verdauungstrakt effizient aufgenommen — mit wenig Rückstand im Darm.

**Novel protein für manche Hunde:**
Viele Hunde haben in ihrem Leben noch kein Putenfleisch bekommen. Als Monoproteinquelle in einer Eliminationsdiät ist Pute daher eine gute Wahl, wenn Hühnchen und Rind schon verbraucht sind.

**Gut akzeptiert:**
Pute hat einen mild-würzigen Eigengeschmack, der von den meisten Hunden gut angenommen wird — auch von Wählern.

## Richtige Zubereitung

1. Putenbrust in ungesalzenem Wasser kochen (kein Öl, keine Gewürze)
2. Komplett durchgaren — 20–25 Minuten kochen
3. In kleine Stücke schneiden oder zerfasern
4. Mit der Kohlenhydratbeilage (Reis, Kartoffel) mischen

Keine Pute mit Haut verwenden — die Haut ist fettreich und würde die Schonkost belasten.

## Für wen ist Pute weniger geeignet?

- Hunde, die bereits auf Geflügel-Proteine reagieren: Bei Hühnchenallergie ist eine Kreuzreaktion auf Pute möglich — nicht ausgeschlossen, aber seltener als oft angenommen. Im Zweifel klären.
- In der Eliminationsdiät: Wenn Pute neu ist, ist sie ein geeignetes Testprotein. Wenn Pute schon gefüttert wurde, suche nach einem wirklich unbekannten Protein.

## Häufige Fragen

### Kann ich Pute auch als dauerhaftes Futter verwenden?
Als Hauptproteinquelle in einer selbst gekochten Ration ja — aber dann braucht es eine berechnete Rezeptur (inkl. Ergänzungen). Als Monoprotein-Diätfutter gibt es auch kommerzielle Produkte.

### Ist Putenklein (Innereien) auch geeignet?
Nein für Schonkost — Innereien wie Leber und Magen sind nährstoffreich, aber schwerer verdaulich und für einen gereizten Darm nicht ideal.`,
