    id: 64,
    slug: "allergie-diaet-dokumentieren",
    title: "Diät bei Allergie streng dokumentieren",
    shortDescription:
      "Das Futtertagebuch ist das wichtigste Werkzeug in der Allergiediagnostik. Was du notieren solltest und wie deine Aufzeichnungen dem Tierarzt helfen.",
    level: 2,
    tags: ["allergie", "tracking"],
    imageUrl: "/images/tipps/diaet/16.jpg",
    imageAlt: "Notizbuch mit Futtertagebuch neben einem Hund mit Hautproblemen",
    content: `Bei Verdacht auf eine Futtermittelallergie ist das Futtertagebuch kein optionales Tool — es ist das entscheidende Diagnostikinstrument. Ohne sorgfältige Dokumentation bleibt die Auswertung der Eliminationsdiät eine Vermutung. Mit einem guten Protokoll wird sie zur Wissenschaft.

## Was ins Futtertagebuch gehört

**Täglich notieren:**
- Was wurde gefüttert? (Hauptfutter, Snacks, Leckerlis, Extras)
- Wie viel wurde gegessen? (vollständig, halb, verweigert)
- Uhrzeit der Mahlzeiten

**Symptome täglich bewerten:**
- Juckreiz (Skala 0–5: 0 = kein Juckreiz, 5 = intensives Kratzen/Kauen)
- Hautveränderungen (Rötungen, Schuppung, Haarausfall — wo genau?)
- Magen-Darm (Kotqualität, Erbrechen, Blähungen)
- Allgemeinbefinden (Energie, Schlaf, Spielfreude)

**Besondere Ereignisse notieren:**
- Ausrutscher (was wurde gegessen, wie viel)
- Umgebungsveränderungen (Kontakt zu anderen Hunden, Putzmittel im Haushalt)
- Medikamentengaben

## Wie du die Daten auswertest

Nach 8 Wochen solltest du eine klare Tendenz sehen:
- **Symptome deutlich rückläufig?** → Die Diät schlägt an; das alte Futter war wahrscheinlich der Auslöser
- **Keine Veränderung?** → Mögliche Erklärungen: Umweltallergie, Parasiten, unentdeckte Ausrutscher, falsches Auslöser-Protein
- **Zeitliche Muster?** → Wenn Symptome immer samstags schlimmer sind (Gassi mit anderen, andere Snacks), zeigt das auf externe Faktoren

## Das Tagebuch beim Tierarzt

Zeige das Protokoll vollständig. Auch Ausrutscher notieren — der Tierarzt braucht das ehrliche Bild, nicht das ideale. Eine Dokumentation, die „alles war perfekt" zeigt, obwohl die Realität anders war, macht die Diagnostik unmöglich.

## Digitale Tools

Smartphone-Fotos der Haut sind ergänzend sehr wertvoll — Vorher-Nachher-Vergleiche machen Verbesserungen sichtbar, die man täglich kaum wahrnimmt.

## Häufige Fragen

### Muss ich wirklich jeden Tag schreiben?
Bei der Eliminationsdiät ja. Nur so siehst du zeitliche Zusammenhänge zwischen Ausrutschern und Symptomen — die nicht immer am gleichen Tag sichtbar werden.

### Wie lange sollte ich das Tagebuch führen?
Mindestens 8 Wochen während der Eliminationsdiät. Bei der Provokationsphase danach ebenfalls sorgfältig weiterführen.`,
