    content: `Du hältst die Eliminationsdiät seit vier Wochen konsequent durch. Dann kommt die Schwiegermutter zu Besuch, der Hund schaut so lieb, und sie gibt ihm ein Stückchen Wurst „damit er auch was bekommt". Fertig. Die Uhr fängt von vorn an.

Das ist frustrierend — aber es ist die Realität, die viele Halter erleben. Rückfälle bei der Allergiediät passieren. Wichtig ist, wie du damit umgehst.

## Warum ein einzelner Rückfall so viel wiegt

Das Immunsystem reagiert auf Allergene mit einer Antikörper-Antwort, die Tage bis Wochen andauern kann. Selbst ein einziges Stück Wurst kann:
- Symptome wieder aufflammen lassen
- Die Beurteilung der Diät unzuverlässig machen
- Die 8-Wochen-Auswertung zurücksetzen, weil nicht mehr klar ist, ob die Symptome vom Rückfall oder von der Diät herrühren

## Was nach einem Rückfall zu tun ist

1. **Notieren:** Was war es? Wann? Wie viel?
2. **Nicht in Panik:** Ein einziger Ausrutscher zerstört nicht alles — aber er muss dokumentiert sein
3. **Beobachten:** Zeigt der Hund in den nächsten 3–10 Tagen Symptome?
4. **Mit dem Tierarzt besprechen:** Ob die Uhr wirklich von vorn anfängt, hängt vom Produkt und der Reaktion ab — manchmal ist eine Verlängerung um 2–3 Wochen ausreichend
5. **Weiterführen:** Die Diät fortsetzen, auch wenn es Frust gibt

## Alle im Haushalt einbeziehen

Das ist vielleicht der wichtigste Schritt überhaupt. Führe ein kurzes Gespräch mit allen, die Zugang zum Hund haben:
- Partner, Kinder, Eltern, Mitbewohner
- Erkläre kurz, was die Diät ist und warum sie wichtig ist
- Gib klare Anweisung: **Kein Futter aus der eigenen Mahlzeit, keine Snacks, keine Ausnahmen**

Manchmal hilft ein Zettel am Kühlschrank oder an der Hundekiste — kurz und klar: „Max ist gerade in der Allergiediät. Bitte nichts füttern außer dem Diätfutter. Danke."

## Häufige Fragen

### Muss ich wirklich von vorn anfangen?
Nicht immer — das hängt von der Reaktion ab. Bei einem kleinen Ausrutscher ohne sichtbare Symptome empfehlen manche Tierärzte einfach die Diät weiterzuführen und die Uhr um eine oder zwei Wochen zu verlängern. Sprich das mit deinem Tierarzt ab.

### Mein Hund wurde von einem fremden Hund abgeleckt. Zählt das?
Wahrscheinlich nicht — die übertragene Proteinmenge ist minimal. Nur wenn bekannt ist, dass der andere Hund kurz vorher das Allergen gefressen hat, könnte es theoretisch relevant sein.`,
