    content: `Ein abgemagerter, unterernährter Hund — ein Fundhund, ein aus schlechter Haltung gerettetes Tier, ein Hund nach schwerer Langzeiterkrankung — weckt den Impuls, sofort zu füttern, viel zu füttern, alles aufzuwiegen. Dieser Impuls ist verständlich und kann gefährlich sein.

## Was das Refeeding-Syndrom ist

Das Refeeding-Syndrom bezeichnet eine potenziell lebensbedrohliche Stoffwechselreaktion, die auftreten kann, wenn ein lang unterernährter Körper plötzlich mit großen Nahrungsmengen konfrontiert wird. Das Phänomen ist beim Menschen gut dokumentiert und kommt auch bei Hunden vor.

**Was passiert:**
Im Hungerstoffwechsel passen sich Insulinspiegel und Elektrolyte (besonders Phosphor, Kalium, Magnesium) an die Mangelzufuhr an. Wenn plötzlich viel Nahrung — besonders Kohlenhydrate — zugeführt wird, schüttet der Körper Insulin aus. Das treibt Phosphor, Kalium und Magnesium schnell in die Zellen. Die Folge: kritisch niedrige Spiegel im Blut. Das kann zu Herzrhythmusstörungen, Muskelschwäche, Krampfanfällen und schlimmstenfalls zum Tod führen.

## Wie du es richtig machst

**Schritt 1: Tierarzt einschalten**
Jeder stark abgemagerte Hund gehört zuerst zum Tierarzt. Eine klinische Beurteilung und ggf. Blutuntersuchungen sind vor dem Aufbau notwendig.

**Schritt 2: Sehr kleine Mengen beginnen**
Beginne mit etwa 25–33 % des errechneten Bedarfs am ersten Tag. Steigere langsam über 5–7 Tage auf die Vollmenge.

**Schritt 3: Eiweißbetonte Kost**
Hochverdauliches Protein ist in der Aufbauphase wichtiger als Kohlenhydrate. Kohlenhydrat-lastige Kost birgt das höchste Refeeding-Risiko.

**Schritt 4: Häufige Kleine Mahlzeiten**
4–6 Mahlzeiten täglich statt einer oder zweier großer Portionen.

**Schritt 5: Engmaschig kontrollieren**
Gewicht täglich, Kotbeschaffenheit, Energie und ggf. Blutwerte in den ersten zwei Wochen.

## Häufige Fragen

### Gibt es spezielles Aufbaufutter für unterernährte Hunde?
Ja — hochverdauliches, proteinreiches Futter (z. B. Gastrointestinal- oder Rekonvaleszenzfutter) ist oft geeignet. Der Tierarzt empfiehlt das Passende. Keine Gainer-Produkte aus dem Sporternährungsbereich.

### Wie lange dauert die Aufbauphase?
Das hängt vom Ausgangszustand ab. Bei leichtem Untergewicht einige Wochen, bei schwerem Marasmus (extremer Auszehrung) mehrere Monate, immer tierärztlich begleitet.`,
