    content: `Medizinisches Diätfutter hat oft einen anderen Geschmack, eine andere Textur und einen anderen Geruch als das gewohnte Futter. Das ist kein Zufall — die veränderte Zusammensetzung beeinflusst das sensorische Profil. Und manche Hunde sind wählerischer als wir uns wünschen. Was tun, wenn der Hund das notwendige Diätfutter verweigert?

## Warum medizinisches Futter abgelehnt wird

- **Veränderte Geschmacksstoffe:** Manche Diäten (z. B. Nierendiät) enthalten weniger Salz und weniger Protein-Aromen — das schmeckt dem Hund fahler
- **Unbekannte Textur:** Andere Konsistenz als gewohnt — besonders beim Wechsel von Nass auf Trocken oder umgekehrt
- **Negative Assoziation:** Wenn das neue Futter in einer Phase eingeführt wird, in der der Hund krank und appetitlos ist, verbindet er das Futter mit dem Unwohlsein

## Was die Akzeptanz erhöht

**Erwärmen:**
Lauwarme Mahlzeiten (nicht heiß) riechen intensiver und werden von den meisten Hunden besser akzeptiert. Wichtig: nicht über 40 °C erhitzen.

**Wasser zugeben:**
Lauwarmes Wasser über Trockenfutter verwandelt es in eine weichere, aromareiche Mahlzeit — oft der einfachste Trick.

**Kleinstmengen zu Beginn:**
Manche Hunde akzeptieren erst nach mehrfachem Anbieten kleinster Mengen — gib nicht nach dem ersten Versuch auf.

**Handreichen:**
Direkt aus der Hand anbieten überbrückt oft die Zurückhaltung. Viele Hunde fressen, was ihnen der Halter anbietet, auch wenn sie es vom Napf verweigern.

**Mischphase:**
Wenn die Diät ein Mischen erlaubt (nicht bei Eliminationsdiät!), langsam angewöhnen.

## Wann zum Tierarzt?

Wenn der Hund über 24 Stunden gar nichts frisst — und das kein gesundheitliches Problem als Ursache hat — ist eine Rücksprache sinnvoll. Manchmal gibt es alternative Produkte im gleichen Diätprogramm mit anderem Geschmacksprofil.

## Häufige Fragen

### Was, wenn alle Tricks nichts helfen?
Dann gibt es in den meisten Diätkategorien mehrere Produkte. Frag deinen Tierarzt nach einer Alternative im gleichen Indikationsbereich. Viele Hersteller bieten auch kostenlose Muster an.

### Darf ich etwas Schmackhaftes hinzufügen?
Bei medizinischen Diäten Vorsicht — viele Zusätze (Brühe, Wurst, Öl) beeinflussen die Zusammensetzung. Im Zweifel fragen, ob ein spezifischer Zusatz toleriert wird.`,
