    id: 71,
    slug: "eliminationsdiät-richtig-durchführen",
    title: "Eliminationsdiät richtig durchführen",
    shortDescription:
      "Die Eliminationsdiät ist der Goldstandard bei Verdacht auf Futtermittelallergie. Wie du sie schrittweise und konsequent durchführst — und warum Halbherzigkeit das Ergebnis zerstört.",
    level: 2,
    tags: ["allergie", "diagnose"],
    imageUrl: "/images/tipps/diaet/23.jpg",
    imageAlt: "Hundehalter notiert Futterzutaten in einem Tagebuch, daneben ein Hundenapf",
    content: `Die Eliminationsdiät ist keine Diät im klassischen Sinne — sie ist ein diagnostisches Werkzeug. Ziel ist es, herauszufinden, ob eine Futtermittelallergie oder -unverträglichkeit für Symptome wie Juckreiz, Ohrentzündungen, Durchfall oder Erbrechen verantwortlich ist. Sie ist aufwändig, aber sie ist die einzige Methode mit wirklich belastbaren Ergebnissen.

## Wie funktioniert das Prinzip?

Du fütterst deinen Hund für acht bis zwölf Wochen ausschließlich mit einer Proteinquelle und einer Kohlenhydratquelle, die er nachweislich noch nie bekommen hat. Das Immunsystem muss sich beruhigen — das dauert Zeit. Nur wenn der Hund in diesem Zeitraum keine bekannten Proteine bekommt, kann man am Ende sicher sagen: „Die Symptome sind besser geworden, also war eine Futtermittelreaktion im Spiel."

## Schritt 1: Die richtige Proteinquelle wählen

Die Proteinquelle muss neu für deinen Hund sein. Gängige „exotische" Optionen sind:
- Pferd
- Känguru
- Strauß
- Kaninchen
- Insekten (Hermetia illucens)
- Wildfleisch

Hat dein Hund bereits alles davon bekommen, kommt hydrolysiertes Futter in Frage — dabei ist das Protein so klein gespalten, dass das Immunsystem es nicht mehr erkennt.

## Schritt 2: Kohlenhydratquelle bestimmen

Auch die Kohlenhydratquelle muss neu oder zumindest neutral sein. Kartoffel, Süßkartoffel oder Tapioka sind häufige Optionen.

## Schritt 3: Absolute Konsequenz acht bis zwölf Wochen

Das ist der schwierigste Teil. Nicht ein einziges Leckerli, kein Stückchen Käse für die Tablette, keine Zahnpflegekauartikel mit unbekannten Zutaten. Schon eine einzige Portion des falschen Proteins setzt die Uhr zurück.

Was erlaubt ist: destilliertes Wasser (kein Leitungswasser, wenn dein Hund darauf reagieren könnte), und die spezifischen Nahrungsergänzungen, die der Tierarzt freigegeben hat.

## Schritt 4: Symptome dokumentieren

Führe ein Tagebuch: Was wird gefüttert, wann, wieviel — und wie sind Juckreiz, Stuhlgang, Haut und Allgemeinzustand? Fotos helfen. Diese Aufzeichnungen sind Gold wert, wenn du zum Tierarzt gehst.

## Schritt 5: Provokationsphase

Wenn sich nach acht bis zwölf Wochen die Symptome deutlich gebessert haben, folgt die Provokationsphase: Du gibst gezielt das alte Futter zurück. Kehren die Symptome zurück, ist die Diagnose bestätigt. Nur dann ist es wirklich eine Futtermittelallergie.

## Häufige Fehler

**Leckerli nicht mitgedacht:** Kommerzielle Snacks enthalten oft viele verschiedene Proteine. Verwende stattdessen kleine Stücke des erlaubten Diätfutters.

**Zu kurze Durchführung:** Sechs Wochen reichen für viele Hunde nicht. Acht bis zwölf Wochen ist die tierärztliche Empfehlung.

**Kein Tierarzt eingebunden:** Ohne Ausgangsbefund weißt du nicht, ob sich tatsächlich etwas verbessert hat.

## Das Wichtigste in Kürze

- Acht bis zwölf Wochen, ein Protein, eine Kohlenhydratquelle — alles neu.
- Absolute Konsequenz: kein einziges verbotenes Leckerli.
- Symptom-Tagebuch führen und Tierarzt regelmäßig einbeziehen.
- Nach der Eliminationsphase gezielte Provokation zur Bestätigung.`,
