    slug: "die-diät-langfristig-evaluieren",
    title: "Die Diät langfristig evaluieren",
    shortDescription:
      "Eine therapeutische Diät ist kein statisches Konzept. Kontrolluntersuchungen, Blutbilder und Anpassungen nach Wochen zeigen, ob und wie die Diät wirkt.",
    level: 2,
    tags: ["kontrolle", "langzeit"],
    imageUrl: "/images/tipps/diaet/1.jpg",
    imageAlt: "Tierärztin wertet Blutwerte eines Hundes aus und bespricht sie mit dem Besitzer",
    content: `Eine therapeutische Diät ist nicht „einmal eingestellt und dann vergessen". Der Körper des Hundes verändert sich — die Erkrankung schreitet fort oder verbessert sich, das Gewicht schwankt, der Appetit ändert sich, neue Probleme entstehen. Ohne regelmäßige Evaluation weißt du nicht, ob die Diät noch passt.

## Was bedeutet Evaluation in der Praxis?

Evaluation heißt: Du und der Tierarzt überprüft in regelmäßigen Abständen, ob die Diät das tut, was sie soll. Das umfasst:

**Körpergewicht und Körperkondition (BCS):**
Wie entwickelt sich das Gewicht? Nimmt der Hund zu, ab oder bleibt er stabil? Der BCS (Body Condition Score, 1–9) gibt einen objektiveren Eindruck als das Gewicht allein — Muskelmasse und Fettverteilung spielen eine Rolle.

**Blutwerte:**
Je nach Erkrankung sind unterschiedliche Werte relevant:
- **Niere:** Kreatinin, BUN, Phosphor, Kalium
- **Leber:** ALT, AST, Bilirubin, Gallensäuren, Kupfer
- **Diabetes:** Blut- und Uringlukose, Fruktosamin
- **Herz:** Elektrolyte, Nierenwerte (Herzmedikamente belasten die Nieren)
- **Schilddrüse:** T4, TSH

**Urinuntersuchung:**
Wichtig bei Harnsteinen und Nierenerkrankungen. pH, Sediment, spezifisches Gewicht und Proteingehalt im Urin zeigen, ob die Diät den Urin wie gewünscht verändert.

**Klinische Zeichen:**
Wie ist das Fell? Wie die Energie? Wie der Stuhlgang? Trinkt der Hund normal? Diese Alltagsbeobachtungen ergänzen die Laborwerte.

## Wie oft kontrollieren?

Das hängt von der Erkrankung und dem Stadium ab. Als grobe Orientierung:
- **Akute Phase (erste Wochen):** Alle zwei bis vier Wochen
- **Stabile chronische Erkrankung:** Alle drei bis sechs Monate
- **Harnsteine in Auflösung:** Monatliche Ultraschallkontrolle bis Steinfreiheit

## Was wenn die Werte sich verschlechtern?

Dann muss die Diät angepasst werden. Mögliche Gründe:
- Die Erkrankung hat sich verschlechtert und erfordert eine restriktivere Diät
- Das Futter passt nicht mehr (z. B. Formulierung geändert)
- Compliance-Probleme (heimliche Snacks)
- Eine neue Erkrankung ist hinzugekommen

## Was wenn die Werte sich verbessern?

Auch das muss besprochen werden. Bei manchen Erkrankungen ist eine Lockerung möglich — zum Beispiel wenn Harnsteine aufgelöst sind oder eine akute Leberentzündung ausgeheilt ist. Nie eigenmächtig absetzen.

## Das Wichtigste in Kürze

- Regelmäßige Blutbild-, Urin- und Gewichtskontrollen sind fester Bestandteil jeder Diät.
- Kontrollintervall je nach Erkrankung und Phase festlegen.
- Verschlechterung = Anpassung, Verbesserung = Rücksprache.
- Eigenbeobachtung im Alltag ergänzt die klinischen Daten.`,
    seoTitle: "Hundediät langfristig evaluieren: Kontrolle und Anpassung | BELLA",
